// Bun has no `module.register`, so the panel points NODE_PATH at
// `<runtime>/js/node_modules`. This wrapper exists only because an npm package
// cannot export a file outside its own directory (`../../host-api/index.mjs` is
// not a legal `exports` target). Re-exporting keeps the canonical
// `host-api/index.mjs` — and therefore `../bus.mjs` — as the single module
// instance shared with runner.mjs.

export * from '../../host-api/index.mjs';
export { default } from '../../host-api/index.mjs';
